themeCSS:
.node.api rect, .node.api polygon, .node.api path, .node.api circle, .node.api ellipse { fill: #4051b5; stroke: #303fa1; }
.node.api .nodeLabel, .node.api .label span, .node.api .label p, .node.api span { color: #ffffff; }
.node.api text { fill: #ffffff; }
.node.api line { stroke: #303fa1; }
.node.model rect, .node.model polygon, .node.model path, .node.model circle, .node.model ellipse { fill: #e7f5f2; stroke: #00897b; }
.node.model .nodeLabel, .node.model .label span, .node.model .label p, .node.model span { color: #10312c; }
.node.model text { fill: #10312c; }
.node.model line { stroke: #00897b; }
.node.ext rect, .node.ext polygon, .node.ext path, .node.ext circle, .node.ext ellipse { fill: #f3f4f7; stroke: #8a91a6; }
.node.ext .nodeLabel, .node.ext .label span, .node.ext .label p, .node.ext span { color: #262b3d; }
.node.ext text { fill: #262b3d; }
.node.ext line { stroke: #8a91a6; }
.node.human rect, .node.human polygon, .node.human path, .node.human circle, .node.human ellipse { fill: #fff4e0; stroke: #e69500; }
.node.human .nodeLabel, .node.human .label span, .node.human .label p, .node.human span { color: #3b2a05; }
.node.human text { fill: #3b2a05; }
.node.human line { stroke: #e69500; }
.node.ok rect, .node.ok polygon, .node.ok path, .node.ok circle, .node.ok ellipse { fill: #e8f5e9; stroke: #2e7d32; }
.node.ok .nodeLabel, .node.ok .label span, .node.ok .label p, .node.ok span { color: #123617; }
.node.ok text { fill: #123617; }
.node.ok line { stroke: #2e7d32; }
.node.bad rect, .node.bad polygon, .node.bad path, .node.bad circle, .node.bad ellipse { fill: #fdecea; stroke: #c62828; }
.node.bad .nodeLabel, .node.bad .label span, .node.bad .label p, .node.bad span { color: #4a1212; }
.node.bad text { fill: #4a1212; }
.node.bad line { stroke: #c62828; }
.node.note rect, .node.note polygon, .node.note path, .node.note circle, .node.note ellipse { fill: #ffffff; stroke: #9aa1b8; }
.node.note .nodeLabel, .node.note .label span, .node.note .label p, .node.note span { color: #4b5570; }
.node.note text { fill: #4b5570; }
.node.note line { stroke: #9aa1b8; }
.node.note rect, .node.note polygon, .node.note path { stroke-dasharray: 5 4; }
.cluster-label span p, .cluster-label .nodeLabel p { background-color: #ffffff !important; padding: 0 6px; }
text.messageText, text.loopText, text.loopText tspan { paint-order: stroke fill; stroke: #ffffff; stroke-width: 10px; stroke-linejoin: round; }
.node circle.state-start { fill: #5f6b8a; stroke: #5f6b8a; }
.node > g.outer-path:not(.label-container) > path { fill: #ffffff; stroke: #5f6b8a; }
.node > g.outer-path:not(.label-container) > g > path { fill: #5f6b8a; stroke: #5f6b8a; }
.edgeLabel, .edgeLabel p, .labelBkg { background-color: #ffffff; }
.edgeLabel rect { opacity: 1; fill: #ffffff; }
.edgeLabel span, .edgeLabel p { color: #4b5570; }
.edgeLabel { font-size: 14px; }
.nodeLabel small, .label small { font-size: 13px; opacity: 0.82; }
.node.list .label div { text-align: left !important; }
.node.list .nodeLabel, .node.list p { font-size: 15px; }
.node.note .nodeLabel, .node.note p { font-size: 14px; }
